// Accedemos al contenido del transcript SRT
const srt = $json.data;

// Dividimos por líneas
const lines = srt.split('\n');

// Inicializamos variables
let frases = [];
let buffer = '';

// Iteramos por cada línea
for (let line of lines) {
  // Ignoramos líneas vacías, números de línea o timestamps
  if (/^\d+$/.test(line.trim()) || line.includes('-->') || line.trim() === '') {
    continue;
  }

  // Acumulamos frases
  buffer += line.trim() + ' ';
}

// Limpiamos y devolvemos el texto final
return [{
  json: {
    transcript_limpio: buffer.trim()
  }
}];
